WITH filtered_shipments AS (SELECT * FROM shipments WHERE order_id IN (10, 22, 28) AND carrier IN ('Kerry', 'UPS')), shipments_stats AS (SELECT CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END AS shipped_cohort, COUNT(*) AS num_shipments, MAX(cost) - MIN(cost) AS cost_range FROM filtered_shipments GROUP BY CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT shipped_cohort, num_shipments, cost_range FROM shipments_stats ORDER BY shipped_cohort DESC;
